-- Run after admin_regression.sql inside BEGIN/ROLLBACK. No real email is sent.
reset role;
select pg_temp.test_assert('anonymous cannot list team',not has_function_privilege('anon','public.admin_team(text,integer)','execute'));
select pg_temp.test_assert('anonymous cannot manage invitations',not has_function_privilege('anon','public.admin_invitation_manage(text,text,text,text)','execute'));
set local role authenticated;
select pg_temp.login_as('customer_auth');
select pg_temp.test_error('customer cannot list team','select public.admin_team()','42501');
select pg_temp.test_error('customer cannot invite','select public.admin_invitation_manage(''create'',''new@example.invalid'')','42501');
select pg_temp.login_as('provider_auth');
select pg_temp.test_error('provider cannot invite','select public.admin_invitation_manage(''create'',''new@example.invalid'')','42501');
select pg_temp.login_as('staff_auth');
select pg_temp.test_error('staff cannot list invitations','select public.admin_team()','42501');
select pg_temp.test_error('staff cannot create Super Admin','select public.admin_invitation_manage(''create'',''new@example.invalid'',''super_admin'')','42501');
select pg_temp.test_error('staff cannot bypass public wrapper','select private.admin_invitation_manage(''create'',''new@example.invalid'')','42501');
select pg_temp.login_as('super_auth','aal1');
select pg_temp.test_error('Super Admin invitation requires MFA','select public.admin_invitation_manage(''create'',''new@example.invalid'')','42501');
select pg_temp.login_as('super_auth');
select pg_temp.test_error('invalid invitation email rejected','select public.admin_invitation_manage(''create'',''not-an-email'')','22023');
select pg_temp.test_error('null invitation action rejected','select public.admin_invitation_manage(null,''new@example.invalid'')','22023');
select pg_temp.test_error('null invitation role rejected','select public.admin_invitation_manage(''create'',''new@example.invalid'',null)','22023');
select pg_temp.test_error('unknown invitation role rejected','select public.admin_invitation_manage(''create'',''new@example.invalid'',''owner'')','22023');
select pg_temp.test_error('mobile account cannot become admin',format('select public.admin_invitation_manage(''create'',%L)',(select email from public.users where user_id=pg_temp.fixture_id('customer_user'))),'22023');
select public.admin_invitation_manage('create','  __TEAM_INVITE@example.invalid  ','staff');
select pg_temp.test_assert('invitation email normalized',public.admin_team('__team_invite')->'items'->0->>'email'='__team_invite@example.invalid');
select pg_temp.test_assert('new invitation pending',public.admin_team('__team_invite')->'items'->0->>'status'='Pending');
select pg_temp.test_assert('invitation expires in seven days',(public.admin_team('__team_invite')->'items'->0->>'expires_at')::timestamptz=now()+interval '7 days');
select pg_temp.test_error('duplicate invitation does not overwrite role','select public.admin_invitation_manage(''create'',''__team_invite@example.invalid'',''super_admin'')','22023');
select pg_temp.test_error('stale invitation changes rejected','select public.admin_invitation_manage(''revoke'',''__team_invite@example.invalid'',''staff'',repeat(''0'',32))','40001');
select public.admin_invitation_manage('revoke','__team_invite@example.invalid','staff',public.admin_team('__team_invite')->'items'->0->>'version');
select pg_temp.test_error('revoked invitation cannot register','select public.admin_registration_check(''__team_invite@example.invalid'')','42501');
select public.admin_invitation_manage('renew','__team_invite@example.invalid','staff',public.admin_team('__team_invite')->'items'->0->>'version');
select pg_temp.test_assert('renewed invitation can register',(public.admin_registration_check('__team_invite@example.invalid')->>'eligible')::boolean);
reset role;
update private.admin_invitations set expires_at=now()-interval '1 second' where email='__team_invite@example.invalid';
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,raw_user_meta_data,created_at,updated_at)
values('eeeeeeee-0000-4000-8000-000000000031','00000000-0000-0000-0000-000000000000','authenticated','authenticated','__team_invite@example.invalid',now(),'{"role":"super_admin"}',now(),now());
set local role authenticated;
select pg_temp.login_as('super_auth');
select pg_temp.test_assert('expired status visible',public.admin_team('__team_invite')->'items'->0->>'status'='Expired');
select pg_temp.test_error('expired invitation registration denied','select public.admin_registration_check(''__team_invite@example.invalid'')','42501');
select set_config('request.jwt.claim.sub','eeeeeeee-0000-4000-8000-000000000031',true);
select set_config('request.jwt.claims','{"sub":"eeeeeeee-0000-4000-8000-000000000031","role":"authenticated","aal":"aal1"}',true);
select pg_temp.test_error('expired invitation activation denied','select public.admin_identity()','42501');
select pg_temp.login_as('super_auth');
select public.admin_invitation_manage('renew','__team_invite@example.invalid','staff',public.admin_team('__team_invite')->'items'->0->>'version');
select set_config('request.jwt.claim.sub','eeeeeeee-0000-4000-8000-000000000031',true);
select set_config('request.jwt.claims','{"sub":"eeeeeeee-0000-4000-8000-000000000031","role":"authenticated","aal":"aal1"}',true);
select pg_temp.test_assert('renewed activation assigns stored role, ignores metadata',public.admin_identity()->>'role_level'='staff');
select pg_temp.test_error('activated admin still needs MFA','select public.admin_list(''users'')','42501');
select pg_temp.login_as('super_auth');
select pg_temp.test_assert('accepted status visible',public.admin_team('__team_invite')->'items'->0->>'status'='Accepted');
select pg_temp.test_error('accepted invitation cannot be revoked','select public.admin_invitation_manage(''revoke'',''__team_invite@example.invalid'',''staff'',repeat(''0'',32))','22023');
select pg_temp.test_error('accepted invitation cannot be renewed','select public.admin_invitation_manage(''renew'',''__team_invite@example.invalid'',''super_admin'',repeat(''0'',32))','22023');
reset role;
select pg_temp.test_assert('all invitation operations audited',(select count(*)=4 from public.audit_logs where target_id=(select invitation_id from private.admin_invitations where email='__team_invite@example.invalid') and actor_id=pg_temp.fixture_id('super_user')));
select pg_temp.test_assert('admin activation creates no customer profile',not exists(select 1 from public.customer_profiles c join public.users u using(user_id) where u.auth_user_id='eeeeeeee-0000-4000-8000-000000000031'));
select jsonb_build_object('passed',count(*)) as admin_invitations_regression from pg_temp.admin_regression_results;
